'use strict';
let provinceFilter='all',detailTee='',statsScope='strict',ruleDraft=null,ruleTarget='draft',ruleReason='';
const V3base={score:scorePage,stats:statsPage,actions:handleAction,table,load,about:settingsPage,manual:manualPage};
const sideNames={skins:'Skins 抢洞',nassau:'拿骚',birdie:'抓鸟奖励',nearest:'最近旗奖',longest:'最远开球奖'};
const completionNames={holed_out:'实际完洞',picked_up:'已捡球',skipped:'已跳洞',conceded_next_stroke:'认可完成'};
const statusNames={pending:'待录入',in_progress:'进行中',incomplete:'未决',decided:'已结算',tied:'平局',unallocated:'有未分配点数',void:'无主赛',provisional:'暂算',processed:'已处理'};
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('');
const fld=(label,html)=>`<label class="v3-field"><span>${label}</span>${html}</label>`;
const select=(id,items,value,extra='')=>`<select id="${id}" ${extra}>${options(items,value)}</select>`;
const numInput=(id,v,min=0,max=54,extra='')=>`<input id="${id}" type="number" inputmode="numeric" min="${min}" max="${max}" value="${v??''}" ${extra}>`;
const fieldText=(id,v='',placeholder='')=>`<input id="${id}" value="${esc(v)}" placeholder="${esc(placeholder)}">`;
const policyLabel=mode=>({official:'正式规则与球场当地规则',custom:'自定义约定',small:'小流氓 · 本场约定',large:'大流氓 · 本场约定',legacy_unspecified:'旧版未记录判罚约定'})[mode];
function rulesSummary(rules,players){const s=rules.scoring;return [R.names[s.type]+(s.type==='record_only'?'':s.basis==='net'?' · 净杆':' · 总杆')+(s.type==='points'?' · '+(s.pointsRule==='8421'?'8421':'标准定分式'):'')+(s.cap?.enabled?' · 封顶':''),rules.grouping.type==='four_ball'?rules.grouping.teams.map(t=>(t.name||t.teamId)+'：'+t.playerIds.map(id=>players.find(p=>p.id===id)?.name||'未选择').join('、')).join(' / '):'个人记分',({none:'不让杆',manual_round_total:'手填本轮让杆总数',manual_hole:'逐洞指定最终让杆'})[rules.handicap.mode],policyLabel(rules.penaltyPolicy.mode),rules.sideGames.length?rules.sideGames.map(g=>sideNames[g.type]).join('、'):'无附加玩法'];}
function sourceNote(c){return c.publicData?'采集于 '+c.retrievedOn+' · 现行记分卡及营业状态待确认':c.demo?'示例球场':'我的球场';}
function courseThumbnail(c){let seed=0;for(const ch of c.id)seed=(seed*31+ch.charCodeAt(0))>>>0;return 'assets/course-thumbs/scene-'+seed%6+'.svg';}
function courseLocation(c){const province=regionLabel(c.province||''),city=(c.city||'').replace(/市$/,'');return [province,city===province?'':city].filter(Boolean).join(' · ')||'地区待核实';}
let directoryLimit=30,directoryFilterKey='';
function regionLabel(p){return ({'内蒙古自治区':'内蒙古','广西壮族自治区':'广西','西藏自治区':'西藏','宁夏回族自治区':'宁夏','新疆维吾尔自治区':'新疆','香港特别行政区':'香港','澳门特别行政区':'澳门'})[p]||p.replace(/[省市]$/,'');}
function courseFacts(c){return c.pars.length?`${c.holes} 洞 · Par ${c.pars.reduce((a,b)=>a+b,0)}`:`${c.reportedHoles?c.reportedHoles+' 洞 · ':''}记分卡待补全`;}
function filteredCourses(){return C.search(db.courses,courseQuery,provinceFilter).filter(c=>courseFilter==='favorites'?db.favorites.includes(c.id):courseFilter==='recent'?db.rounds.some(r=>r.courseId===c.id):true);}
function provincePicker(){const counts=Object.fromEntries(C.regions.map(p=>[p,db.courses.filter(c=>c.province===p).length]));modal('选择地区',`<p class="tiny">数字为已收录的球场／分场条目，包含资料待补全记录。</p><div class="province-options">${[['all','全国',db.courses.filter(c=>c.publicData).length],...C.regions.map(p=>[p,regionLabel(p),counts[p]])].map(([v,t,n])=>action('v3-province',`<b>${t}</b><small>${n} 条</small>`,`province-option ${provinceFilter===v?'active':''}`,`data-value="${v}" aria-pressed="${provinceFilter===v}"`)).join('')}</div>`);}
courseCards=function(){const key=[provinceFilter,courseQuery,courseFilter].join('|');if(key!==directoryFilterKey){directoryFilterKey=key;directoryLimit=30;}const cs=filteredCourses();return `<p class="tiny course-count">找到 ${cs.length} 条球场记录${cs.length>directoryLimit?' · 已显示 '+directoryLimit+' 条':''}</p>`+(cs.length?cs.slice(0,directoryLimit).map(c=>{const selectMode=route.q.has('select'),ready=C.canScore(c),path=(selectMode&&ready?'create/':'course/')+c.id;return `<article class="card directory-card compact-course"><button class="course-open" data-action="go" data-path="${esc(path)}" aria-label="${selectMode&&ready?'选择':'查看'}${esc(c.name)}"><img class="course-thumbnail" src="${courseThumbnail(c)}" alt="${esc(c.name)} · 球场示意配图" loading="lazy"><span class="course-copy"><strong>${esc(c.name)}</strong><span class="course-meta">${esc(courseLocation(c))} · ${courseFacts(c)}</span><span class="course-segments ${c.operationStatus==='closed_reported'?'course-closed':''}">${c.operationStatus==='closed_reported'?'来源标注已关闭':c.pars.length?C.sections(c).map(s=>esc(s.name)).join(' / ')+(c.tees.length?' · '+c.tees.length+' 发球台':' · 发球台待补'):'已收录基础资料 · 逐洞 Par 待补'}</span></span><span class="course-arrow" aria-hidden="true">${icon('chevron')}</span></button>${action('favorite',icon('star'),'course-favorite icon-btn '+(db.favorites.includes(c.id)?'saved-star':''),`data-id="${c.id}" aria-pressed="${db.favorites.includes(c.id)}" aria-label="收藏${esc(c.name)}"`)}${action('course-navigate',icon('pin'),'course-nav-shortcut icon-btn',`data-id="${esc(c.id)}" aria-label="导航到${esc(c.name)}"`)}</article>`;}).join('')+(cs.length>directoryLimit?action('v3-more-courses','加载更多球场（剩余 '+(cs.length-directoryLimit)+' 条）','btn outline full'):'' ):empty('暂无匹配的球场资料','试试其他地区或关键词，也可按现行记分卡手动添加；未收录不代表当地没有球场。','manual','手动添加'));};
coursesPage=function(){const total=db.courses.filter(c=>c.publicData).length,regions=new Set(db.courses.filter(c=>c.publicData).map(c=>c.province)).size;return `${title('下一场，去哪里？','全国球场目录 · '+total+' 条公开资料')}<div class="directory-banner"><b>把全国球场，装进口袋。</b><p>${regions} 个地区 · 包含港澳台</p><span>选一座城市，开启下一场好球</span></div><div class="search">${icon('search')}<input id="course-search" value="${esc(courseQuery)}" placeholder="球场名称、别名、城市" aria-label="搜索球场"></div>${action('v3-regions',`<span>${icon('pin')}<b>${provinceFilter==='all'?'全国 · 全部地区':esc(regionLabel(provinceFilter))}</b></span><span>切换地区 ${icon('chevron')}</span>`,'directory-region-trigger','aria-haspopup="dialog"')}<div class="chips">${[['all','全部球场'],['recent','最近打过'],['favorites','我的收藏']].map(([v,t])=>action('course-filter',t,`chip ${courseFilter===v?'active':''}`,`data-value="${v}"`)).join('')}</div><div id="course-list">${courseCards()}</div>${go('manual',icon('plus')+' 手动添加球场','btn outline full')}<p class="tiny" style="margin:15px 0">全国资料采集于 2026-10-23，长三角保留已核对的 2026-10-19 版本。配图为示意插画；公开目录不等于完整在营名录，现行记分卡请向球会核对。</p>`;};
manualPage=function(){let html=V3base.manual();const c=db.courses.find(c=>c.id===route.q.get('source'));if(!c)return html;html=html.replace('<input name="name"','<input name="name" value="'+esc(c.name)+'"').replace('<input name="city"','<input name="city" value="'+esc(c.city||'')+'"');return `<div class="notice">${icon('info')}<span>为 ${esc(c.name)} 补全本次使用的记分卡，保存为“我的球场”。请逐洞核对，公开目录资料保持原样。</span></div>`+html;};
courseDetail=function(){const c=db.courses.find(c=>c.id===route.id);if(!c)return empty('球场不存在','','courses');const t=c.teeData?.find(t=>t.id===detailTee)||c.teeData?.[0];return `${title(c.name,c.nameEn||c.city)}<div class="card"><div class="row">${pill(c.province||'我的球场')}${action('favorite',icon('star')+(db.favorites.includes(c.id)?'已收藏':'收藏'),'text-link',`data-id="${c.id}"`)}</div><div class="metrics"><div class="metric"><b>${c.holes||c.reportedHoles||'—'}</b><span>${c.holes?'已取得逐洞参数':'简介标注球洞'}</span></div><div class="metric"><b>${c.pars.length?c.pars.reduce((a,b)=>a+b,0):'—'}</b><span>全部洞段 Par 合计</span></div><div class="metric"><b>${c.tees.length||'—'}</b><span>发球台</span></div></div>${action('course-navigate',icon('pin')+'<span>'+esc(c.address||c.city||c.province||'按球场名称查找')+'</span><b>导航</b>'+icon('chevron'),'course-address-link',`data-id="${esc(c.id)}" aria-label="导航到${esc(c.name)}"`)}${c.phone?`<a class="text-link" href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:''}<p class="tiny" style="margin-top:12px">${sourceNote(c)}</p></div>${c.holes&&c.reportedHoles&&c.reportedHoles!==c.holes?`<div class="notice warning">目录标注 ${c.reportedHoles} 洞，已取得记分卡 ${c.holes} 洞，以实际选择洞段为本轮依据。</div>`:''}${!c.pars.length?'<div class="notice warning">公开资料暂缺可靠的逐洞Par，不能根据总Par生成球洞。'+(c.operationStatus==='closed_reported'?'资料仅供查询。':'可按现行记分卡手动补全后记分。')+'</div>':''}${c.operationStatus==='closed_reported'?'<div class="notice warning">来源标注该球场已关闭，暂不开放新建球局；保留资料供查询。</div>':''}${section('洞段与记分卡')}<p class="tiny">多洞段球场由你按实际打球顺序组合，不预设官方比赛组合。</p>${t?`<div class="v3-field"><span>选择发球台</span>${action('v3-course-tee',`<span class="tee-dot" style="--tee-color:${teeInfo(t.name).color}"></span><b>${esc(t.name)}</b>${icon('chevron')}`,'course-tee-trigger',`aria-haspopup="dialog" aria-label="选择发球台：${esc(t.name)}"`)}</div>`:''}${C.sections(c).map(s=>`<div class="card"><div class="row"><h3>${esc(s.name)}</h3><span class="tiny">9 洞 · Par ${s.holes.reduce((a,h)=>a+h.par,0)}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>洞</th><th>Par</th><th>SI</th><th>${esc(t?.name||'距离')} · 码</th></tr></thead><tbody>${s.holes.map(h=>`<tr><td>${esc(h.label)}</td><td>${h.par}</td><td>${h.si??'—'}${h.siStatus==='invalid_18_hole_sequence'?' ⚠':''}</td><td>${t?.distances[h.id]??'—'}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}<div class="notice">${icon('info')}<span>SI 未经现行适用范围确认，不能当作官方差点依据。距离为记分卡码数，不是实时 GPS 距离。</span></div><details class="card"><summary>资料来源与待核实事项</summary>${(c.issues||[]).map(i=>`<p class="tiny" style="margin:12px 0">${esc(i.detail)} ${esc(i.action)}</p>`).join('')}${(c.sources||[]).map(s=>`<a class="source-link" target="_blank" rel="noopener" href="${esc(s.url)}">${esc(s.publisher)} · ${esc(s.title)}</a>`).join('')}</details>${C.canScore(c)?go('create/'+c.id,'在这里开始记分 '+icon('arrow'),'btn primary full'):c.operationStatus==='closed_reported'?'':go('manual?source='+c.id,'补全记分卡后开始 '+icon('arrow'),'btn primary full')}`;};
ensureDraft=function(){const cid=route.id||db.draft?.courseId||db.courses[0]?.id,c=db.courses.find(c=>c.id===cid);if(!c||!C.canScore(c))return null;if(!db.draft||db.draft.courseId!==cid)db.draft={courseId:cid,date:G.date(),time:new Date().toTimeString().slice(0,5),start:1,players:[{id:'me',name:db.profile.name,tee:c.tees[0]||'未指定'}],segmentIds:C.sections(c).slice(0,2).map(s=>s.id),ruleSnapshot:R.defaultRules()};const d=db.draft;d.segmentIds=d.segmentIds||C.sections(c).slice(0,d.holes==='front'?1:2).map(s=>s.id);d.ruleSnapshot=d.ruleSnapshot||R.defaultRules();return d;};
function previewDraft(d=db.draft,rules=d.ruleSnapshot){const c=db.courses.find(c=>c.id===d.courseId),h=C.selectedHoles(c,d.segmentIds,Number(d.start));return {id:'preview',revision:0,status:'draft',schemaVersion:3,...h,players:C.playerSnapshots(c,d.players,h.holes),courseSnapshot:C.snapshot(c,d.segmentIds),ruleSnapshot:rules,scores:Object.fromEntries(d.players.map(p=>[p.id,{}])),events:[],awards:[]};}
createPage=function(){const d=ensureDraft();if(!d)return empty('该球场暂不能直接开局','记分卡缺项或来源标注已关闭，请在球场详情中核对。','courses?select=1','返回选择球场');const c=db.courses.find(c=>c.id===d.courseId),ss=C.sections(c);let error='';try{R.validateRuleConfig(previewDraft());}catch(e){error=e.message;}return `<div class="steps"><span class="active"></span><span class="active"></span><span></span></div><div class="card"><div class="row"><h3>${esc(c.name)}</h3>${go('courses?select=1','更换','text-link')}</div><p class="tiny">${sourceNote(c)}</p></div><div class="form-label">日期与开球时间</div><div class="grid2"><input id="draft-date" type="date" aria-label="打球日期" value="${d.date}"><input id="draft-time" type="time" aria-label="开球时间" value="${d.time}"></div><div class="form-label">按顺序选择本轮洞段 <span>1 段 9 洞 / 2 段 18 洞</span></div><div class="card"><div class="grid2">${fld('第一洞段',select('segment-first',ss.map(s=>[s.id,s.name]),d.segmentIds[0]))}${fld('第二洞段',select('segment-second',[['','只打 9 洞'],...ss.map(s=>[s.id,s.name])],d.segmentIds[1]||''))}</div>${d.segmentIds.length===2?fld('出发顺序',select('v3-start',[[1,'从第 1 洞开始'],[10,'从第 10 洞开始']],d.start)):''}<p class="tiny">本轮洞号按所选顺序编为 1–${d.segmentIds.length*9}；原始球洞编号保留在记分卡。</p></div><div class="row"><div class="form-label">同组球友 · ${d.players.length}/4 人</div>${d.players.length<4?action('add-player','＋ 添加球友','text-link'):''}</div><div class="card">${d.players.map((p,i)=>`<div class="player-row">${av(p,i)}<div class="grow"><b>${esc(p.name)}</b><small>${p.id==='me'?'我 · 代记员':'同组球友'}</small></div>${action('v3-choose-tee',`<span class="tee-dot" style="--tee-color:${teeInfo(p.tee).color}"></span><span class="tee-trigger-copy"><small>发球台</small><b>${esc(teeInfo(p.tee).name)}</b></span>${icon('chevron')}`,'tee-trigger',`data-player="${esc(p.id)}" aria-haspopup="dialog" aria-label="${esc(p.name)}的发球台：${esc(teeInfo(p.tee).name)}"`)}${p.id==='me'?'<span class="player-remove-slot" aria-hidden="true"></span>':action('remove-player',icon('close'),'icon-btn',`data-id="${p.id}" aria-label="移除${esc(p.name)}"`)}</div>`).join('')}</div><div class="form-label">常用玩法 <span>需要净杆时请显式设置让杆</span></div><div class="chips wrap">${[['record_only','仅记分'],['stroke_play','个人比杆'],['match_play','两人比洞'],['four_ball','四人两队比洞'],['points','8421 积分']].map(([v,t])=>action('v3-template',t,`chip ${d.ruleSnapshot.scoring.type===v?'active':''}`,`data-value="${v}"`)).join('')}</div><div class="row"><div class="form-label">本轮五项设置</div>${action('v3-rules','修改规则 '+icon('chevron'),'text-link')}</div><div class="card rule-summary">${rulesSummary(d.ruleSnapshot,d.players).map((s,i)=>`<div><small>${['记分方式','组队方式','让杆方式','判罚约定','附加玩法'][i]}</small><b>${esc(s)}</b></div>`).join('')}</div><div class="round-actions">${action('v3-allowance','查看让杆预览','btn outline')}${action('v3-templates','我的常用规则','btn outline')}</div>${error?`<div class="notice warning" role="alert">${icon('info')}<span>${esc(error)}</span></div>`:`<div class="notice">${icon('check')}<span>设置完整。由你代表本组确认规则，开局后每次记分自动保存。</span></div>`}<div class="dock">${action('create-round','确认规则，开始记分 '+icon('arrow'),'btn primary')}</div>`;};
function teeInfo(name){const map={black:['黑 Tee','#29372f'],blue:['蓝 Tee','#427db0'],white:['白 Tee','#ffffff'],red:['红 Tee','#c66c61'],yellow:['黄 Tee','#d7b35e'],gold:['金 Tee','#b99b56'],green:['绿 Tee','#5e9667'],silver:['银 Tee','#a8b3b4'],orange:['橙 Tee','#d48d4c']},key=String(name).toLowerCase(),item=map[key];return {name:item?item[0]:name,color:item?item[1]:'#889b75',original:name};}
function showTeePicker(pid){const d=ensureDraft(),p=d.players.find(p=>p.id===pid),c=db.courses.find(c=>c.id===d.courseId);if(!p)return;if(!c.tees.length){modal('发球台待补全','<p>公开资料未列出发球台，当前使用“未指定”。可以正常记分，距离保持空白。</p>');return;}const holes=C.selectedHoles(c,d.segmentIds,Number(d.start)).holes;modal(p.name+' · 选择发球台',`<p>按本人本轮实际使用的发球台选择。</p><div class="tee-options">${c.tees.map((name,i)=>{const info=teeInfo(name),t=c.teeData?.find(t=>t.name===name),distances=holes.map(h=>t?.distances?.[h.sourceHoleId||h.id]),total=distances.every(n=>Number.isFinite(n))?distances.reduce((a,b)=>a+b,0):null;return action('v3-set-tee',`<span class="tee-dot" style="--tee-color:${info.color}"></span><span class="grow"><b>${esc(info.name)}</b><small>${esc(name)}${total!==null?' · 本轮 '+total.toLocaleString()+' 码':''}</small></span><span class="tee-radio" aria-hidden="true">${name===p.tee?icon('check'):''}</span>`,'tee-option '+(name===p.tee?'selected':''),`data-player="${esc(pid)}" data-tee-index="${i}" aria-pressed="${name===p.tee}"`);}).join('')}</div>`);}
function showCourseTeePicker(){const c=db.courses.find(c=>c.id===route.id);if(!c?.teeData?.length)return;const current=c.teeData.find(t=>t.id===detailTee)||c.teeData[0];modal('选择发球台',`<p>选择后更新该发球台的逐洞距离。</p><div class="tee-options">${c.teeData.map((t,i)=>action('v3-course-tee-set',`<span class="tee-dot" style="--tee-color:${teeInfo(t.name).color}"></span><span class="grow"><b>${esc(t.name)}</b></span><span class="tee-radio" aria-hidden="true">${t.id===current.id?icon('check'):''}</span>`,'tee-option '+(t.id===current.id?'selected':''),`data-tee-index="${i}" aria-pressed="${t.id===current.id}"`)).join('')}</div>`);}
function ruleContext(){return ruleTarget==='draft'?previewDraft(db.draft,ruleDraft):{...G.clone(round()),ruleSnapshot:ruleDraft};}
function readRulesForm(){const f=$('#v3-rules-form');if(!f)return ruleDraft;const val=id=>$('#'+id)?.value,checked=id=>!!$('#'+id)?.checked,rr=G.clone(ruleDraft),ctx=ruleContext(),ps=ctx.players;rr.scoring={type:val('rule-type'),basis:val('rule-basis')||'gross'};if(rr.scoring.type==='points')rr.scoring.pointsRule=val('rule-points')||'8421';if(rr.scoring.type==='match_play')rr.scoring.tiePolicy='allow_tie';if(rr.scoring.type==='stroke_play')rr.scoring.cap={enabled:val('rule-cap')!=='none',rule:val('rule-cap')==='none'?undefined:val('rule-cap')};rr.grouping={type:val('rule-group'),teams:[]};if(rr.grouping.type==='four_ball')rr.grouping.teams=['A','B'].map(id=>({teamId:id,name:id+' 队',playerIds:ps.filter((p,i)=>val('team-'+i)===id).map(p=>p.id)}));rr.handicap={mode:val('rule-handicap')};if(rr.handicap.mode==='manual_round_total'){rr.handicap.totals=Object.fromEntries(ps.map((p,i)=>[p.id,val('total-'+i)===''?null:Number(val('total-'+i))]));rr.handicap.siConfirmed=checked('si-confirmed');}if(rr.handicap.mode==='manual_hole')rr.handicap.perHole=Object.fromEntries(ps.map((p,i)=>[p.id,Object.fromEntries(R.order(ctx).map(n=>[n,val('allow-'+i+'-'+n)===''?null:Number(val('allow-'+i+'-'+n))]))]));rr.penaltyPolicy={mode:val('rule-policy'),localRules:(val('local-rules')||'').split('\n').filter(Boolean)};if(!['official','legacy_unspecified'].includes(rr.penaltyPolicy.mode))rr.penaltyPolicy.topics=R.topics.map((_,i)=>Object.fromEntries(['action','outcome','area','note'].map(k=>[k,val('policy-'+i+'-'+k)||''])));rr.sideGames=Object.keys(sideNames).filter(t=>checked('side-'+t)).map(t=>{const old=ruleDraft.sideGames.find(g=>g.type===t);const g={id:old?.id||'sg-'+t,type:t};if(t==='skins')g.carry=val('skins-carry')!=='false';if(t==='birdie')g.basis=val('birdie-basis')||'gross';if(['nearest','longest'].includes(t)){g.holeNumbers=(val(t+'-holes')||'').split(/[,，\s]+/).filter(Boolean).map(Number);g.unit=val(t+'-unit')||'m';g.qualification=checked(t+'-qualify');}return g;});return rr;}
function showRules(){const rr=ruleDraft,ctx=ruleContext(),sc=rr.scoring,hc=rr.handicap,pol=rr.penaltyPolicy,ns=R.order(ctx);modal(ruleTarget==='draft'?'本轮玩法设置':'整轮规则修订',`<form id="v3-rules-form"><p class="tiny">先选比赛方式，再设置让杆和附加玩法。总杆始终是实际输入，不会被计算结果覆盖。</p><div class="form-label">① 记分方式</div>${fld('主赛',select('rule-type',Object.entries(R.names),sc.type,'data-rule-structure'))}${sc.type!=='record_only'?fld('成绩口径',select('rule-basis',[['gross','总杆'],['net','净杆 · 扣除本洞让杆']],sc.basis,'data-rule-structure')):''}${sc.type==='points'?fld('积分表',select('rule-points',[['stableford','标准定分式'],['8421','8421 积分']],sc.pointsRule)):''}${sc.type==='stroke_play'?fld('比杆形式',select('rule-cap',[['none','常规实际杆数'],['double_par','双倍 Par 封顶'],['par_plus_three','Par + 3 封顶'],['fixed_ten','固定 10 杆封顶'],['net_double_bogey','净双柏忌封顶']],sc.cap?.enabled?sc.cap.rule:'none','data-rule-structure')):''}<div class="form-label">② 组队方式</div>${fld('组队',select('rule-group',[['individual','个人'],['four_ball','固定两人队 · 四球赛']],rr.grouping.type,'data-rule-structure'))}${rr.grouping.type==='four_ball'?ctx.players.map((p,i)=>fld(esc(p.name),select('team-'+i,[['A','A 队'],['B','B 队']],rr.grouping.teams.find(t=>t.playerIds.includes(p.id))?.teamId||(i<2?'A':'B')))).join(''):''}<div class="form-label">③ 让杆方式</div>${fld('手动约定',select('rule-handicap',[['none','不让杆'],['manual_round_total','手填本轮总数 · 需有效 SI'],['manual_hole','逐洞指定最终让杆']],hc.mode,'data-rule-structure'))}${hc.mode==='manual_round_total'?`<p class="tiny">${ns.length} 洞填写 0–${ns.length*3} 杆；比洞会先减去全组最低总数，再按 SI 分配。</p>${ctx.players.map((p,i)=>fld(esc(p.name),numInput('total-'+i,hc.totals?.[p.id],0,ns.length*3))).join('')}<label class="check-row"><input id="si-confirmed" type="checkbox" ${hc.siConfirmed?'checked':''}><span>已核对本轮组合、发球台、现行记分卡 SI 的适用范围</span></label>`:''}${hc.mode==='manual_hole'?`<p class="tiny">每格明确填写 0–3 杆。这是最终逐洞让杆，不再减去最低者。</p><div class="table-scroll"><table class="allowance-table"><thead><tr><th>洞</th>${ctx.players.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${ns.map(n=>`<tr><td>${n}</td>${ctx.players.map((p,i)=>`<td>${numInput('allow-'+i+'-'+n,hc.perHole?.[p.id]?.[n],0,3,`aria-label="${esc(p.name)}第${n}洞让杆"`)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${action('v3-zero-allow','将尚未填写的格子设为 0','btn outline full')}`:''}<div class="form-label">④ 判罚约定</div>${fld('本场约定',select('rule-policy',[['official','正式规则与当地规则'],['custom','自定义'],['small','小流氓 · 逐项确认'],['large','大流氓 · 逐项确认'],...(pol.mode==='legacy_unspecified'?[['legacy_unspecified','旧版未记录']]:[])],pol.mode,'data-rule-structure'))}${pol.mode==='official'?'<p class="tiny">适用正式规则；本程序不根据杆数自动推断违规或处罚。当地规则可逐行记录。</p><textarea id="local-rules" placeholder="当地规则或委员会说明（选填）">'+esc((pol.localRules||[]).join('\n'))+'</textarea>':pol.mode==='legacy_unspecified'?'<p class="tiny">旧记录未保存判罚约定，不能自动追认为正式规则。</p>':`<p class="tiny">名称没有统一罚则，请按本组约定完整填写七项。</p>${R.topics.map((t,i)=>`<details class="policy-topic" ${i===0?'open':''}><summary>${i+1}. ${t}</summary>${[['action','如何处理'],['outcome','罚几杆 / 洞结果'],['area','适用区域'],['note','补充说明']].map(([k,t])=>fld(t,fieldText('policy-'+i+'-'+k,pol.topics?.[i]?.[k]||''))).join('')}</details>`).join('')}`}<div class="form-label">⑤ 附加玩法</div>${Object.entries(sideNames).map(([t,name])=>{const g=rr.sideGames.find(g=>g.type===t);return `<div class="side-setting"><label class="check-row"><input id="side-${t}" type="checkbox" ${g?'checked':''} data-rule-structure><span>${name}</span></label>${g&&t==='skins'?fld('并列处理',select('skins-carry',[[true,'并列滚存'],[false,'并列不滚存']],g.carry!==false)):''}${g&&t==='birdie'?fld('抓鸟口径',select('birdie-basis',[['gross','实际总杆'],['net','净杆 · 使用本轮让杆']],g.basis||'gross')):''}${g&&['nearest','longest'].includes(t)?`${fld('参与球洞',fieldText(t+'-holes',(g.holeNumbers||[]).join(','),'例如 3,8,12'))}${fld('距离单位',select(t+'-unit',[['m','米'],['yd','码']],g.unit||'m'))}<label class="check-row"><input type="checkbox" id="${t}-qualify" ${g.qualification?'checked':''}><span>须${t==='nearest'?'上果岭':'上球道'}才可获奖</span></label>`:''}</div>`;}).join('')}<div id="rule-error" class="notice warning hidden"></div><div class="modal-actions">${action('v3-save-template','保存为常用规则','btn outline')}${action('v3-rules-save','保存设置','btn primary')}</div></form>`);}
function previewAllowances(ctx){let a;try{R.validateRuleConfig(ctx);a=R.allowances(ctx);}catch(e){return `<div class="notice warning">${esc(e.message)}</div>`;}return `<p class="tiny">净杆 = 总杆 − 本洞让杆。手动总数不等于官方差点。</p><div class="table-scroll"><table class="data-table"><tr><th>洞 / SI</th>${ctx.players.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr>${R.order(ctx).map(n=>`<tr><td>${n} / ${R.si(ctx,ctx.players[0].id,n)??'—'}</td>${ctx.players.map(p=>`<td>${a[p.id][n]}</td>`).join('')}</tr>`).join('')}<tr><th>合计</th>${ctx.players.map(p=>`<th>${Object.values(a[p.id]).reduce((a,b)=>a+b,0)}</th>`).join('')}</tr></table></div>`;}
function rulesView(r){return `<div class="card rule-summary">${rulesSummary(r.ruleSnapshot,r.players).map((s,i)=>`<div><small>${['记分方式','组队方式','让杆方式','判罚约定','附加玩法'][i]}</small><b>${esc(s)}</b></div>`).join('')}</div><p class="tiny">规则 ${esc(r.ruleSnapshot.ruleVersion)} · 计算 ${esc(r.ruleSnapshot.engineVersion)} · 修订 ${r.revision}</p>${(r.ruleSnapshot.penaltyPolicy.localRules||[]).map(t=>`<p>${esc(t)}</p>`).join('')}${(r.ruleSnapshot.penaltyPolicy.topics||[]).map((t,i)=>`<div class="card"><h3>${R.topics[i]}</h3>${Object.values(t).map(v=>`<p class="tiny">${esc(v)}</p>`).join('')}</div>`).join('')}${previewAllowances(r)}`;}
const scoreTerms=[[-4,'condor',''],[-3,'albatross',''],[-2,'eagle','Eagle'],[-1,'birdie','Birdie'],[0,'par','Par'],[1,'bogey','Bogey'],[2,'double','Double'],[3,'triple',''],[4,'others','']];
function scoreAppearance(gross,par,completion='holed_out'){
 if(completion!=='holed_out')return {kind:'special',label:completionNames[completion]||'未记录',short:({picked_up:'捡球',skipped:'跳洞',conceded_next_stroke:'认可'})[completion]||'—',difference:'实际总杆留空'};
 const d=gross-par,term=scoreTerms.find(t=>t[0]===d)||(d>4?scoreTerms[8]:[-5,'condor','']),kind=term[1],label=term[2];
 return {kind,label,short:label,difference:d===0?'Even Par':(d<0?Math.abs(d)+' under Par':d+' over Par')+(gross===1?' · Hole-in-one':''),delta:d===0?'E':d>0?'+'+d:String(d)};
}
function scoreLegend(){return `<div class="score-legend english-score-guide" aria-label="Score guide">${scoreTerms.filter(([d])=>[-2,-1,0,1,2].includes(d)).map(([d,k,t])=>`<span><i class="score-mark ${k}" aria-hidden="true">${d===0?'E':d>0?'+'+d:String(d)}</i>${t}</span>`).join('')}</div>`;}
table=function(r,full=false,legend=true){const half=scoreHalf??(r.currentHole>9?'back':'front'),hs=full?r.holes:r.holes.filter(h=>half==='front'?h.number<=9:h.number>9);return `${!full&&r.holes.length===18?`<div class="segment">${[['front','前九洞'],['back','后九洞']].map(([v,t])=>action('half',t,half===v?'active':'',`data-value="${v}"`)).join('')}</div>`:''}<div class="table-scroll scorecard-scroll"><table class="scorecard-table ${full?'full-table':'nine-hole-table'}">${!full?`<colgroup><col style="width:12%">${hs.map(()=>'<col>').join('')}<col style="width:11%"></colgroup>`:''}<thead><tr><th scope="col">球洞</th>${hs.map(h=>`<th scope="col" class="${r.currentHole===h.number?'current':''}" title="${esc((h.sectionName||'')+' '+(h.label||h.number))}">${h.number}</th>`).join('')}<th scope="col">总杆</th></tr></thead><tbody><tr class="par-row"><th scope="row">PAR</th>${hs.map(h=>`<td>${h.par}</td>`).join('')}<td title="本轮全部球洞标准杆">${r.holes.reduce((n,h)=>n+h.par,0)}</td></tr>${r.players.map(p=>`<tr><th scope="row">${esc(p.id==='me'?'我':p.name)}</th>${hs.map(h=>{const s=r.scores[p.id]?.[h.number],v=!s?'—':s.completion==='picked_up'?'捡':s.completion==='skipped'?'跳':s.completion==='conceded_next_stroke'?'认'+s.grossStrokes:s.grossStrokes,a=s?scoreAppearance(s.grossStrokes,h.par,s.completion):null;return `<td>${action('cell',`<span class="score-mark ${a?.kind||'blank'}">${v}</span>`,`cell-btn ${s?'':'blank'} ${r.currentHole===h.number&&r.currentPlayer===p.id?'selected':''}`,`data-rid="${r.id}" data-id="${p.id}" data-hole="${h.number}" aria-label="${esc(p.name)}第${h.number}洞${v}${a?.label?'，'+esc(a.label):''}" title="${a?esc((a.label?a.label+' · ':'')+a.difference):'尚未记分'}"`)}</td>`;}).join('')}<td class="score-total" title="本轮标准杆 + 已记录球洞杆差；未完洞按当前杆差" aria-label="${esc(p.name)}总杆 ${GolfScoreTotals.summary(r,p.id).liveTotal}">${GolfScoreTotals.summary(r,p.id).liveTotal}</td></tr>`).join('')}</tbody></table></div>${full?'<p class="tiny round-total-note">总杆 = 本轮标准杆 + 已记录球洞杆差；未完洞按当前杆差显示。</p>':''}${legend?scoreLegend():''}`;};
function scoreExtras(r){const {h,p,s}=current(),d=R.derivePlayerHole(r,p.id,h.number,undefined,r.ruleSnapshot.scoring.type==='match_play'?'main':undefined);const team=r.ruleSnapshot.grouping.teams?.find(t=>t.playerIds.includes(p.id));const th=team?R.deriveTeamHole(r,team,h.number,undefined,'main'):null;return `<div class="calculation-card"><div class="row"><b>${esc(completionNames[s?.completion]||'尚未记录')}</b>${action('v3-show-rules','本场规则','text-link')}</div><p>${esc(d.explanation)}</p>${th?`<p>${esc(th.explanation)}${th.usedPlayerIds?.length?' · 采用 '+th.usedPlayerIds.map(id=>esc(r.players.find(p=>p.id===id).name)).join('、'):''}</p>`:''}<small>${esc(h.sectionName||'')}${h.label?' · 原洞号 '+esc(h.label):''} · ${esc(p.tee)} · ${p.holeDistances?.[h.number]??'—'} 码</small></div><div class="chips wrap">${action('v3-special','捡球 / 跳洞','chip')}${action('v3-penalty','追加罚杆','chip')}${action('v3-event','比赛事件','chip')}${action('v3-award','附加奖项','chip')}</div>`;}
scorePage=function(){
 const r=round();if(!r)return empty('未找到球局','','play');const base=V3base.score();if(!base)return '';
 const h=r.holes.find(h=>h.number===r.currentHole)||r.holes[0],p=r.players.find(p=>p.id===r.currentPlayer)||r.players[0],cs=r.scores[p.id]?.[h.number],sum=GolfScoreTotals.summary(r,p.id),a=cs?.completion==='holed_out'?scoreAppearance(cs.grossStrokes,h.par):null;
 const rawValue=cs?(cs.grossStrokes??'—'):h.par;
 const status=saveError?'保存失败':edit?'更正尚未提交':cs?'已保存':'待记分';
 const detail=a?`<span class="entry-outcome ${a.kind}">${a.label?esc(a.label)+' · ':''}${a.delta}</span>`:cs?`<span class="entry-note">${esc(completionNames[cs.completion])}</span>`:'<span class="entry-note">点中间数字，记录 Par</span>';
 const tabs=r.players.length>1?`<div class="player-tabs compact-player-tabs">${r.players.map((pl,i)=>action('select-player',av(pl,i)+`<span>${esc(pl.id==='me'?'我':pl.name)}</span>${r.scores[pl.id]?.[h.number]?'<i class="player-done" aria-hidden="true"></i>':''}`,`player-tab ${pl.id===p.id?'active':''}`,`data-id="${esc(pl.id)}" aria-label="切换到${esc(pl.name)}" aria-pressed="${pl.id===p.id}"`)).join('')}</div>`:'';
 const tailStart=base.indexOf('<button class="technical-toggle"');let tail=tailStart>=0?base.slice(tailStart):'';tail=tail.replace(/<button class="text-link" data-action="withdraw"[\s\S]*?<\/button>/,'');
 return `<div class="scoring-workspace">${edit?'<div class="readonly">更正模式 · 修改后提交更正</div>':''}<div class="score-top"><div><h2>${esc(r.courseName)}</h2><p class="tiny">${r.players.length} 位球友 · ${r.holes.length} 洞</p></div><span class="save-state ${saveError?'error':''}">${icon(saveError?'info':'check')}${status}</span></div><div class="hole-heading"><div class="current-hole-title"><div><small>当前球洞</small><h1>第 ${h.number} 洞</h1></div><div class="current-par"><span>标准杆</span><b>PAR ${h.par}</b></div></div><div class="progress"><b>${sum.played}</b> / ${r.holes.length} 洞<br>已记录</div></div>${table(r,false,false)}<section class="card score-panel compact-score-panel" aria-label="本洞记分">${tabs}<div class="compact-entry-row"><div class="entry-caption"><span>${r.players.length===1?'我的':'当前球友'}本洞总杆</span>${detail}</div><div class="stepper">${action('score-step',icon('minus'),'step-btn',`data-delta="-1" aria-label="减少总杆" ${p.withdrawn?'disabled':''}`)}${action('v3-confirm-par',`<span>${rawValue}</span>${!cs?'<small>点击记 Par</small>':''}`,`score-value ${cs?'':'pending'}`,`aria-label="${!cs?'按 Par '+h.par+' 记录':'本洞已记 '+rawValue+' 杆'}" ${p.withdrawn?'disabled':''}`)}${action('score-step',icon('plus'),'step-btn plus',`data-delta="1" aria-label="增加总杆" ${p.withdrawn?'disabled':''}`)}</div></div><div class="compact-entry-footer"><span class="entry-round-total"><span>总杆 <b>${sum.liveTotal}</b> 杆 <span class="entry-diff">${sum.played?sum.diffText:'E'}</span></span><small>Par ${sum.roundPar}${sum.diff>0?' + '+sum.diff:sum.diff<0?' − '+Math.abs(sum.diff):''} · ${sum.complete?'全部完洞':sum.played?'按当前杆差':'尚未记分'}</small></span><div>${cs?action('clear-score','清空','compact-clear'):''}${action('v3-undo',icon('undo'),'compact-undo','aria-label="撤销上次操作" title="撤销上次操作"')}</div></div></section>${scoreLegend()}<details class="score-more"><summary>本洞详情与比赛操作 ${icon('chevron')}</summary><div class="tiny">总杆已包含罚杆，推杆与命中状态可在详细记录中填写。</div>${scoreExtras(r)}</details>${tail}</div>`;
};
function numberText(n){return typeof n==='object'?n.denominator===1?String(n.numerator):`${n.numerator}/${n.denominator}`:String(n);}
function resultsHTML(r){const out=R.buildRoundSummary(r),m=out.main,name=id=>r.players.find(p=>p.id===id)?.name||R.competitors(r).find(p=>p.id===id)?.name||id;let main='';if(r.ruleSnapshot.scoring.type==='record_only')main=`<div class="notice">${icon('book')}<span>本轮仅记分，不设主赛名次。以下实际成绩按同组球友顺序展示。</span></div>`;else if(r.ruleSnapshot.scoring.type==='match_play')main=`<div class="card contest-result"><span class="tag">${statusNames[m.status]}</span><h2>${esc(m.result)}</h2><p>${m.winnerId?esc(name(m.winnerId))+'获胜':''}</p><small>${esc(m.explanation)}</small></div>`;else main=`<div class="card"><div class="row"><h3>${R.names[r.ruleSnapshot.scoring.type]} · ${r.ruleSnapshot.scoring.basis==='net'?'净杆':'总杆'}</h3>${pill(m.final?'已结算':'暂算','gray')}</div>${m.rows.map(row=>`<div class="rank-row"><b>${row.rank||'—'}</b><div class="grow"><b>${esc(row.name)}</b><small>${row.played}/${r.holes.length} 洞</small></div><span class="total">${row.played?row.total:'—'}<small>${m.unit}</small></span></div>`).join('')}<p class="tiny">${esc(m.explanation)}</p></div>`;return `${section('主赛结果')}${main}${out.sideGames.length?section('附加玩法 · 独立结算'):''}${out.sideGames.map(g=>`<div class="card side-result"><div class="row"><h3>${sideNames[g.type]}</h3>${pill(statusNames[g.status]||g.status,g.status==='incomplete'?'gold':'green')}</div>${g.contests?g.contests.map((c,i)=>`<div class="rank-row"><span class="grow">${['前九','后九','全场'][i]}</span><b>${esc(c.result)}</b><small>${c.winnerId?esc(name(c.winnerId)):''}</small></div>`).join(''):''}<div class="award-totals">${Object.entries(g.totals||{}).map(([id,v])=>`<span>${esc(name(id))}<b>${numberText(v)} ${g.unit}</b></span>`).join('')}</div>${g.unallocated?`<p class="tiny">最后未分配 ${g.unallocated} 点，保留原池，不平分。</p>`:''}${g.holes?`<details><summary class="tiny">逐洞明细 / 未决原因</summary>${g.holes.map(h=>`<p class="tiny">第 ${h.number} 洞${h.playerId?' · '+esc(name(h.playerId)):''}：${statusNames[h.status]||h.status}${h.winnerId?' · '+esc(name(h.winnerId)):''}${h.points?' +'+h.points+'点':''}${h.pool?' · 池 '+h.pool+'点':''}${h.explanation?' · '+esc(h.explanation):''}</p>`).join('')}</details>`:''}</div>`).join('')}`;}
resultPage=function(){const r=round();if(!r)return empty('未找到球局','','history');const mine=R.rawSummary(r,'me');return `<div class="result-hero"><div class="eyebrow">EVERY STROKE HAS A STORY</div><h2>${esc(r.courseName)}</h2><p>${r.date} · ${r.holes.length} 洞 · 修订 ${r.revision}</p><div class="result-score">${mine.totalText}<small>实际杆</small></div><div class="result-meta">${mine.diffText} · 实际完洞 ${mine.played}/${r.holes.length}</div>${pill(R.isFinished(r)?r.status==='finished_complete'?'本轮已结束':'部分完成':'进行中')}</div>${resultsHTML(r)}${section('原始实际成绩')}<div class="card">${r.players.map((p,i)=>{const s=R.rawSummary(r,p.id);return `<div class="rank-row">${av(p,i)}<div class="grow"><b>${esc(p.name)}</b><small>实际完洞 ${s.played}/${r.holes.length} · 已处理 ${s.processed} 洞</small></div><b>${s.totalText} 杆</b></div>`;}).join('')}</div><p class="tiny">实际总杆仅合计实际完洞。捡球、跳洞、比洞让步不会补成 0 杆或封顶杆。</p>${go('card/'+r.id,'完整记分卡','btn outline full')}<div class="round-actions">${action('v3-show-rules','本场规则与让杆','btn outline')}${action('v3-logs','查看修订记录','btn outline')}</div>${R.isFinished(r)?`<div class="round-actions">${action('begin-edit','更正成绩','btn outline',`data-id="${r.id}"`)}${action('share','分享我的成绩','btn primary',`data-id="${r.id}"`)}</div>`:`<div class="round-actions">${action('resume','继续记分','btn secondary',`data-id="${r.id}"`)}${action('finish','检查并结束','btn primary',`data-id="${r.id}"`)}</div>`}${action('v3-revise-rules','更正整轮规则 / Par / SI','text-link','style="margin-top:16px"')}${Object.values(r.scores).some(scores=>Object.values(scores).some(s=>s.completionSource==='legacy_assumed'))?action('v3-confirm-sources','核对旧记录来源','btn outline full','style="margin-top:16px"'):''}`;};
statsPage=function(){return `<div class="chips wrap">${[['strict','正式实际成绩'],['custom','自定义 / 封顶'],['legacy','旧版统计']].map(([v,t])=>action('v3-stats-scope',t,`chip ${statsScope===v?'active':''}`,`data-value="${v}"`)).join('')}</div>`+V3base.stats()+`<div class="notice">${icon('info')}<span>${statsScope==='strict'?'仅计入规则与来源明确、全部实际完洞的正式记录；技术均值只按明确填写项计算。':statsScope==='legacy'?'旧版推杆来源不明，保留原值供记分卡查看，不计入明确填写的推杆均值。':'展示自定义或封顶球局中实际完洞的成绩。捡球不会产生实际总杆。'}</span></div>`;};
function applyOp(op){const r=round();try{const n=R.applyOperation(r,{...op,operationId:G.uid(),baseRevision:r.revision,time:Date.now()});if(saveRound(n)){render();return true;}}catch(e){toast(e.message);}return false;}
writeScore=function(s){const r=round();try{const prepared=s?{...s,green:s.gir!==undefined?s.gir:s.green,grossStrokes:s.strokes,completion:s.completion||'holed_out'}:null;if(prepared&&prepared.grossStrokes!==null&&['picked_up','skipped'].includes(prepared.completion)){prepared.completion='holed_out';prepared.grossStrokes=prepared.strokes;}const n=R.applyOperation(r,{type:'score',operationId:G.uid(),baseRevision:r.revision,time:Date.now(),playerId:r.currentPlayer,holeNumber:r.currentHole,score:prepared});if(saveRound(n,r,true))render();}catch(e){toast(e.message);}};
finish=function(id){const r=db.rounds.find(r=>r.id===id);if(!r)return;let next;try{next=S3.finishRound(r,Date.now());}catch(e){return toast(e.message);}const m=R.buildRoundSummary(r),missing=r.players.reduce((a,p)=>a+r.holes.length-R.rawSummary(r,p.id).processed,0),pending=m.sideGames.filter(g=>g.status==='incomplete');confirmBox('检查并结束本轮',`尚有 ${missing} 条球洞状态未填写。主赛：${statusNames[m.main.status]}。${pending.length?'未决附加项：'+pending.map(g=>sideNames[g.type]).join('、')+'。':''}可按现状结束；缺失成绩保持空白，未决项目不会自动判胜。`,()=>{if(saveRound(next,r)){undo=null;nav('result/'+id);}},missing||pending.length?'保存部分结果':'确认结束');};
saveEdit=function(){if(!edit)return;const e=edit;const before=R.buildRoundSummary(e.original),after=R.buildRoundSummary(e.copy);modal('确认成绩更正',`<p class="tiny">所有主赛、Skins 滚存、拿骚与个人统计将按新记录重新计算。</p><div class="card">${e.copy.players.map(p=>`<p>${esc(p.name)}：实际 ${R.rawSummary(e.original,p.id).totalText} → ${R.rawSummary(e.copy,p.id).totalText} 杆</p>`).join('')}<p>主赛：${esc(S3.describeResult(e.original))} → ${esc(S3.describeResult(e.copy))}</p></div><form data-v3-form="commit-correction"><label>更正原因（必填）<textarea name="reason" required placeholder="例如：第 8 洞少记一杆"></textarea></label><button class="btn primary full" type="submit">确认更正并生成新修订</button></form>`);};
function eventForm(){const r=round(),match=r.ruleSnapshot.scoring.type==='match_play',nassau=r.ruleSnapshot.sideGames.some(g=>g.type==='nassau');const scopes=[...(r.mainContestId?[['main','主赛 / 全场']]:[]),...(nassau?[['nassau-front','拿骚前九'],['nassau-back','拿骚后九']]:[]),...r.ruleSnapshot.sideGames.filter(g=>g.type==='skins').map(g=>[g.id,'Skins'])];if(!scopes.length)return toast('本轮仅记分，未配置需要裁定的比赛');modal('比赛事件',`<p class="tiny">只影响所选比赛范围，不补写实际总杆。让步不可反悔；录入错误可说明原因更正。</p><form data-v3-form="event">${fld('作用范围',select('event-scope',scopes,'main'))}${fld('事件',select('event-type',[...(match?[['concede_hole','对手让出本洞'],['concede_match','对手让出本场'],['loss_of_hole','裁定对手本洞负'],['conceded_next_stroke','认可下一杆完成']]:[]),['disqualified','取消资格（选中方）'],['withdrawn','退出本比赛（选中方）'],...(r.ruleSnapshot.sideGames.some(g=>g.type==='skins')?[['void_hole','Skins 本洞作废']]:[])],match?'concede_hole':'disqualified'))}${fld('受益方 / 被裁定方',select('event-party',[...R.competitors(r).map(c=>[c.id,c.name]),...r.ruleSnapshot.grouping.type==='four_ball'?r.players.map(p=>[p.id,p.name+'（认可下一杆）']):[]],r.currentPlayer))}${fld('认可下一杆后的记分总杆（仅认可时填）',numInput('event-credited',null,1,30))}${fld('原因',`<textarea id="event-reason" required></textarea>`)}<button class="btn primary full" type="submit">确认保存比赛事件</button></form>`);}
function awardsForm(){const r=round(),gs=r.ruleSnapshot.sideGames.filter(g=>['nearest','longest'].includes(g.type)&&g.holeNumbers.includes(r.currentHole));if(!gs.length)return toast('当前洞没有设置最近旗或最远开球奖');modal('第 '+r.currentHole+' 洞奖项',`<p class="tiny">由记分员人工确认，不从定位或杆数推断赢家。并列均分 1 分。</p><form data-v3-form="award">${fld('奖项',select('award-game',gs.map(g=>[g.id,sideNames[g.type]]),gs[0].id))}${fld('结果',select('award-status',[['pending','尚未录入'],['none','无人达标'],['winner','一位赢家'],['tie','并列赢家']],'pending'))}<div class="form-label">获奖者（赢家 / 并列时选择）</div>${r.players.map(p=>`<label class="check-row"><input type="checkbox" name="award-winner" value="${p.id}"><span>${esc(p.name)}</span></label>`).join('')}${fld('距离（选填，单位按本项规则）',numInput('award-distance',null,0,1000))}<label class="check-row"><input type="checkbox" id="award-qualified"><span>已核实获奖者满足本项上果岭 / 上球道条件</span></label>${fld('备注',fieldText('award-note'))}<button class="btn primary full" type="submit">保存奖项结果</button></form>`);}
handleAction=async function(el,event){let a=el.dataset.action;const v=el.dataset.value;if(a==='undo')a='v3-undo';if(a==='about'){modal('青野 · 高尔夫记分','<p>已接入全国 '+GolfCourseData.courses.length+' 条球场／分场资料及 V3.1 记分规则。球局本地保存，支持数据备份；球场现行版本与营业状态需核实。</p>');return;}if(!a.startsWith('v3-'))return V3base.actions(el,event);
 if(a==='v3-confirm-sources'){modal('核对旧记录来源',`<p>先通过整轮规则更正填写当时的规则，再逐项核对旧记分卡。仅当所有已有杆数均为实际完洞时确认；原有推杆仍保持来源未知。</p><form data-v3-form="sources"><label class="check-row"><input type="checkbox" name="actual" required><span>我已核对本轮全部已有杆数，均为实际完洞成绩</span></label><label>核对来源与原因<textarea name="reason" required></textarea></label><button class="btn primary full">确认来源并保留修订</button></form>`);return;}
 if(a==='v3-confirm-par'){const {h,p,s}=current();if(p.withdrawn||s)return;writeScore({strokes:h.par,completion:'holed_out',putts:null,penalties:0,fairway:null,green:null,gir:null});return;}
 if(a==='v3-course-tee'){showCourseTeePicker();return;}
 if(a==='v3-course-tee-set'){const c=db.courses.find(c=>c.id===route.id),t=c?.teeData?.[Number(el.dataset.teeIndex)];if(t){detailTee=t.id;render();closeModal();}return;}
 if(a==='v3-choose-tee'){showTeePicker(el.dataset.player);return;}
 if(a==='v3-set-tee'){const d=ensureDraft(),c=db.courses.find(c=>c.id===d.courseId),tee=c.tees[Number(el.dataset.teeIndex)],pid=el.dataset.player;if(!tee)return;changeDraft(d=>{const p=d.players.find(p=>p.id===pid);if(p)p.tee=tee;});closeModal();return;}
 if(a==='v3-regions'){provincePicker();return;}
 if(a==='v3-more-courses'){directoryLimit+=30;$('#course-list').innerHTML=courseCards();return;}
 if(a==='v3-province'){provinceFilter=v;render();closeModal();return;}
 if(a==='v3-template'){const d=ensureDraft(),rr=R.defaultRules(v==='four_ball'?'match_play':v);if(v==='four_ball')rr.grouping={type:'four_ball',teams:[{teamId:'A',name:'A 队',playerIds:d.players.slice(0,2).map(p=>p.id)},{teamId:'B',name:'B 队',playerIds:d.players.slice(2,4).map(p=>p.id)}]};confirmBox('应用快捷玩法', '将替换本轮五项规则设置，球友和球场保留。开始前会重新核对人数、洞段及让杆。',()=>changeDraft(d=>d.ruleSnapshot=rr),'应用此玩法');}
 if(a==='v3-rules'){ruleTarget='draft';ruleDraft=G.clone(db.draft.ruleSnapshot);showRules();}
 if(a==='v3-rules-save'){ruleDraft=readRulesForm();try{R.validateRuleConfig(ruleContext());}catch(e){$('#rule-error').classList.remove('hidden');$('#rule-error').textContent=e.message;$('#rule-error').scrollIntoView({block:'nearest'});return;}if(ruleTarget==='draft'){changeDraft(d=>d.ruleSnapshot=ruleDraft);closeModal();}else {const r=round(),rules=G.clone(ruleDraft);closeModal();modal('确认整轮规则修订',`<p>原规则：${esc(rulesSummary(r.ruleSnapshot,r.players).join('；'))}</p><p>新规则：${esc(rulesSummary(rules,r.players).join('；'))}</p><p class="tiny">本轮所有已记成绩会重新结算。</p><form data-v3-form="rules-correction"><label>修订原因<textarea name="reason" required></textarea></label><button class="btn primary full">确认整轮修订</button></form>`);}}
 if(a==='v3-zero-allow'){for(const input of document.querySelectorAll('[id^="allow-"]'))if(input.value==='')input.value='0';}
 if(a==='v3-allowance')modal('本轮让杆预览',previewAllowances(previewDraft()));
 if(a==='v3-show-rules'){const r=round();modal('本场规则 · 修订 '+r.revision,rulesView(r));}
 if(a==='v3-quick'){const {s}=current();writeScore({...s,completion:'holed_out',strokes:Number(v),grossStrokes:Number(v),putts:s?.putts??null,penalties:s?.penalties??0,fairway:s?.fairway??null,green:s?.green??null});}
 if(a==='v3-special'){const r=round();modal('本洞特殊状态',`<form data-v3-form="special">${fld('状态',select('special-status',[['picked_up','捡球 / 本洞不计个人有效成绩'],['skipped','跳洞 · 保留待补'],...r.ruleSnapshot.penaltyPolicy.mode!=='official'?[['conceded_next_stroke','自定义约定认可完成']]:[]],'picked_up'))}${fld('已击球次数（选填）',numInput('special-taken',null,0,30))}${fld('认可完成总杆（只在认可时填写）',numInput('special-gross',null,1,30))}${fld('原因 / 约定说明',`<textarea id="special-reason" required></textarea>`)}<button class="btn primary full">确认本洞状态</button></form>`);}
 if(a==='v3-penalty'){const {s}=current();if(!s||s.grossStrokes==null)return toast('请先填写本洞实际总杆');modal('追加罚杆',`<p>当前总杆 ${s.grossStrokes}（已含罚杆 ${s.penalties}）。下方确认后同时增加总杆和罚杆分项。</p><form data-v3-form="penalty">${fld('追加罚杆',numInput('penalty-amount',1,1,30))}${fld('原因',`<textarea id="penalty-reason" required></textarea>`)}<button class="btn primary full">预览追加结果</button></form>`);}
 if(a==='v3-event')eventForm();if(a==='v3-award')awardsForm();
 if(a==='v3-undo'){const r=round(),last=r.changeLog.at(-1);if(!last||last.newRevision!==r.revision||last.kind==='undo')return toast('没有可撤销的最近操作');if(last.kind==='event'){modal('更正错误录入的比赛事件',`<p>实际发生的让步不可撤回。仅在记错对象或范围时使用。</p><form data-v3-form="event-undo"><label class="check-row"><input type="checkbox" required><span>这是录入错误，不是反悔让步</span></label><textarea name="reason" required placeholder="写明录入错误"></textarea><button class="btn primary full">确认错误更正</button></form>`);}else applyOp({type:'undo',targetId:last.operationId,reason:'撤销上次录入'});}
 if(a==='v3-stats-scope'){statsScope=v;render();}
 if(a==='v3-logs'){const r=round();modal('修订与更正记录',`<p class="tiny">当前修订 ${r.revision} · 每次变更保留旧值和规则快照</p>${r.changeLog.slice().reverse().map(l=>`<details class="card"><summary>修订 ${l.newRevision} · ${esc(l.reason)}</summary><p class="tiny">${new Date(l.time).toLocaleString('zh-CN')}</p><pre class="json-detail">${esc(JSON.stringify({变更前:l.before,变更后:l.after},null,2))}</pre></details>`).join('')||'<p>暂无变更记录</p>'}`);}
 if(a==='v3-revise-rules'){const r=round();ruleTarget='round';ruleDraft=G.clone(r.ruleSnapshot);modal('更正整轮规则',`<p>统一替换本轮规则或球洞资料，历史保留旧版本。仅影响这场球。</p>${action('v3-open-rules','修订玩法与让杆','btn outline full')}${action('v3-edit-parsi','修订本轮 Par / SI','btn outline full','style="margin-top:12px"')}`);}
 if(a==='v3-open-rules')showRules();
 if(a==='v3-edit-parsi'){const r=round();modal('本轮 Par / SI 修订',`<form data-v3-form="parsi"><p class="tiny">以下值将统一应用于本轮所有球友；不会改动球场目录或其他历史记录。</p><div class="table-scroll"><table class="data-table"><tr><th>洞</th><th>Par</th><th>SI（未知留空）</th></tr>${r.holes.map(h=>`<tr><td>${h.number}</td><td>${numInput('fix-par-'+h.number,h.par,3,6)}</td><td>${numInput('fix-si-'+h.number,R.si(r,r.players[0].id,h.number),1,18)}</td></tr>`).join('')}</table></div><label>更正原因<textarea name="reason" required></textarea></label><button class="btn primary full">核对并整轮更正</button></form>`);}
 if(a==='v3-save-template'){ruleDraft=readRulesForm();try{R.validateRuleConfig(ruleContext());}catch(e){return toast(e.message);}const value=S3.portableTemplate(ruleDraft,ruleContext().players);modal('保存常用规则',`<form data-v3-form="template"><p>只保存规则参数；不保存球友身份、球场或成绩。</p><input name="name" maxlength="24" required placeholder="例如：周末四球比洞"><button class="btn primary full" style="margin-top:16px">保存模板</button></form>`);ruleDraft=value;}
 if(a==='v3-templates')modal('我的常用规则',db.templates.length?db.templates.map(t=>action('v3-use-template',esc(t.name),'menu-row',`data-id="${t.id}"`)).join(''):'<p>先进入玩法设置，完成配置后保存为常用规则。</p>');
 if(a==='v3-use-template'){const t=db.templates.find(t=>t.id===el.dataset.id);confirmBox('应用常用规则','将替换本轮玩法；按当前球友位置映射规则，并重新校验 SI、洞段与人数。',()=>{changeDraft(d=>d.ruleSnapshot=S3.applyTemplate(t.rules,d.players));},'应用');}
};
document.addEventListener('change',event=>{const e=event.target;
 if(['segment-first','segment-second','v3-start'].includes(e.id)){const first=$('#segment-first').value,second=$('#segment-second').value,start=Number($('#v3-start')?.value||1);if(first===second){toast('请选两个不同的洞段');render();return;}const next=[first,...second?[second]:[]];const apply=()=>changeDraft(d=>{d.segmentIds=next;d.start=next.length===1?1:start;d.ruleSnapshot.handicap={mode:'none'};d.ruleSnapshot.sideGames=[];});if(db.draft.ruleSnapshot.handicap.mode!=='none'||db.draft.ruleSnapshot.sideGames.length)confirmBox('洞段改变影响规则','确认后将清除原让杆分配与附加玩法，请按新洞段重新设置。',apply,'确认更换');else apply();}
 if(e.hasAttribute('data-rule-structure')){let next=readRulesForm();const changedValue=e.value,previousValues={'rule-type':ruleDraft.scoring.type,'rule-basis':ruleDraft.scoring.basis,'rule-group':ruleDraft.grouping.type,'rule-cap':ruleDraft.scoring.cap?.enabled?ruleDraft.scoring.cap.rule:'none'};if(e.id in previousValues)e.value=previousValues[e.id];const prev=readRulesForm();e.value=changedValue;const apply=()=>{if(e.id==='rule-type') {if(next.scoring.type==='record_only'){next.scoring.basis='gross';next.grouping={type:'individual',teams:[]};next.handicap={mode:'none'};}next.sideGames=[];}if(e.id==='rule-basis'&&next.scoring.basis==='gross'){next.handicap={mode:'none'};if(next.scoring.cap?.rule==='net_double_bogey')next.scoring.cap={enabled:false};next.sideGames=next.sideGames.filter(g=>g.basis!=='net');}if(e.id==='rule-group')next.sideGames=[];if(e.id==='rule-cap'&&next.scoring.cap?.rule==='net_double_bogey')next.scoring.basis='net';if(e.id==='rule-handicap'&&next.handicap.mode!=='none')next.scoring.basis='net';ruleDraft=next;showRules();};if(['rule-type','rule-basis','rule-group'].includes(e.id)||e.id==='rule-cap'&&next.scoring.cap?.rule==='net_double_bogey'&&prev.scoring.basis==='gross'){modal('确认设置联动',`<p>切换后会重新校验人数，并清除受影响的让杆或附加玩法配置。</p>`,`<div class="modal-actions">${action('v3-cancel-rule-link','取消','btn outline')}${action('v3-confirm-rule-link','确认切换','btn primary')}</div>`);window.v3RuleLink={apply,cancel:()=>{ruleDraft=prev;showRules();}};}else apply();}
});
const v3ActionsWithLinks=handleAction;handleAction=async function(el,e){if(el.dataset.action==='v3-confirm-rule-link')return window.v3RuleLink.apply();if(el.dataset.action==='v3-cancel-rule-link')return window.v3RuleLink.cancel();return v3ActionsWithLinks(el,e);};
document.addEventListener('submit',event=>{const f=event.target,type=f.dataset.v3Form;if(!type)return;event.preventDefault();const fd=new FormData(f),val=id=>$('#'+id)?.value,r=round();try{
 if(type==='special'){const completion=val('special-status'),gross=completion==='conceded_next_stroke'?Number(val('special-gross')):null;const s={completion,grossStrokes:gross,strokes:gross,putts:null,penalties:0,fairway:null,green:null,reason:val('special-reason'),strokesTaken:val('special-taken')===''?null:Number(val('special-taken')),concededStrokes:completion==='conceded_next_stroke'?1:0};R.validateScore(s);if(applyOp({type:'score',playerId:r.currentPlayer,holeNumber:r.currentHole,score:s}))closeModal();}
 if(type==='penalty'){const amount=Number(val('penalty-amount')),reason=val('penalty-reason'),s=r.scores[r.currentPlayer][r.currentHole];if(!reason.trim())throw Error('请填写原因');confirmBox('确认追加罚杆',`总杆 ${s.grossStrokes} → ${s.grossStrokes+amount}；罚杆分项 ${s.penalties} → ${s.penalties+amount}。原因：${reason}`,()=>applyOp({type:'append_penalty',playerId:r.currentPlayer,holeNumber:r.currentHole,amount,reason}),'确认同时更新');}
 if(type==='event'){const e={contestId:val('event-scope'),type:val('event-type'),beneficiary:val('event-party'),holeNumber:r.currentHole,reason:val('event-reason'),creditedGross:val('event-credited')===''?null:Number(val('event-credited'))};R.validateEvent(r,e);if(applyOp({type:'event',event:e,reason:e.reason}))closeModal();}
 if(type==='award'){const g=r.ruleSnapshot.sideGames.find(g=>g.id===val('award-game')),e={sideGameId:g.id,holeNumber:r.currentHole,status:val('award-status'),winnerIds:fd.getAll('award-winner'),measurement:val('award-distance')===''?null:Number(val('award-distance')),unit:g.unit,qualified:$('#award-qualified').checked,note:val('award-note')};R.validateAward(r,e);if(applyOp({type:'award',award:e}))closeModal();}
 if(type==='event-undo'){if(applyOp({type:'undo',targetId:r.changeLog.at(-1).operationId,entryError:true,reason:String(fd.get('reason'))}))closeModal();}
 if(type==='sources'){if(applyOp({type:'confirm_sources',reason:String(fd.get('reason')).trim(),actualConfirmed:fd.has('actual')}))closeModal();}
 if(type==='commit-correction'){const e=edit,reason=String(fd.get('reason')).trim();const next=R.applyOperation(e.original,{type:'correction',operationId:G.uid(),baseRevision:e.original.revision,time:Date.now(),reason,changes:{scores:e.copy.scores,events:e.copy.events,awards:e.copy.awards,ruleSnapshot:e.copy.ruleSnapshot,holes:e.copy.holes,players:e.copy.players}});if(update(d=>{const i=d.rounds.findIndex(r=>r.id===e.id);if(d.rounds[i].revision!==e.original.revision)throw Error('原球局已变化，请刷新后重新更正');d.rounds[i]=next;})){edit=null;closeModal();nav('result/'+next.id);}}
 if(type==='rules-correction'||type==='parsi'){const reason=String(fd.get('reason')).trim(),rules=type==='rules-correction'?ruleDraft:r.ruleSnapshot,holes=G.clone(r.holes),players=G.clone(r.players);if(type==='parsi')for(const h of holes){h.par=Number(val('fix-par-'+h.number));h.si=val('fix-si-'+h.number)===''?null:Number(val('fix-si-'+h.number));h.siStatus='user_confirmed';players.forEach(p=>{p.holePars[h.number]=h.par;p.holeSI[h.number]=h.si;});}const preview={...G.clone(r),ruleSnapshot:rules,holes,players};R.validateRuleConfig(preview);const before=R.evaluateContest(r),after=R.evaluateContest(preview);const difference=JSON.stringify(before.rows?.map(x=>[x.name,x.total])||before.result)+' → '+JSON.stringify(after.rows?.map(x=>[x.name,x.total])||after.result);confirmBox('确认整轮重新结算','本次更正将应用到所有已记球洞。主赛前后：'+difference,()=>{if(R.isFinished(r)){const n=R.applyOperation(r,{type:'correction',operationId:G.uid(),baseRevision:r.revision,time:Date.now(),reason,changes:{ruleSnapshot:rules,holes,players}});if(saveRound(n,r)){render();}}else applyOp({type:'rules',rules,holes,players,reason});},'确认修订');}
 if(type==='template'){const name=String(fd.get('name')).trim();if(update(d=>d.templates.push({id:G.uid(),name,rules:ruleDraft}))){closeModal();toast('常用规则已保存');}}
 }catch(e){toast(e.message);}});

const baseCardV3=cardPage;
cardPage=function(){const r=round();if(!r)return baseCardV3();const main=R.evaluateContest(r),scope=r.ruleSnapshot.scoring.type==='match_play'?'main':undefined;return baseCardV3()+section('逐洞计算明细')+`<p class="tiny">${esc(rulesSummary(r.ruleSnapshot,r.players)[0])}。让杆与计算值独立展示，实际杆数保持原始记录。</p>`+r.players.map(p=>`<details class="card" open><summary>${esc(p.name)} · ${esc(p.tee)}</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>洞 / Par</th><th>实际杆</th><th>让杆</th><th>净杆</th><th>计分</th></tr></thead><tbody>${r.holes.map(h=>{const d=R.derivePlayerHole(r,p.id,h.number,undefined,scope);return `<tr><td>${h.number} / ${h.par}</td><td>${d.gross??'—'}</td><td>${d.allowance}</td><td>${d.net??'—'}</td><td>${d.value??'—'}</td></tr><tr><td colspan="5" class="tiny" style="text-align:left">${esc(d.explanation)}</td></tr>`;}).join('')}</tbody></table></div></details>`).join('')+(r.ruleSnapshot.scoring.type==='match_play'?`<div class="card"><h3>比洞进度 · ${esc(main.result)}</h3><p class="tiny">${esc(main.explanation)}</p></div>`:'');};
render();
